return function(row)
  local source = type(row) == "table" and row or {}
  local function clean(value)
    if type(value) ~= "number" or value < 0 or value % 1 ~= 0 then return 0 end
    return value
  end
  return { coins = clean(source.coins), xp = clean(source.xp) }
end

